css:
.wc-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.wc-stage canvas { touch-action: none; cursor: grab; }
.wc-stage canvas.holding { cursor: grabbing; }
.wc-meter { display: grid; gap: 4px; margin: 0; }
.wc-meter p { display: grid; grid-template-columns: 5.2em 1fr 2.6em; align-items: center; gap: 8px; margin: 0; font-size: 18px; }
.wc-meter em { display: block; height: 14px; background: #e6e9ee; border-radius: 7px; overflow: hidden; }
.wc-meter i { display: block; height: 100%; width: 0; border-radius: 7px; transition: width .3s; }
.wc-ev i { background: #f0a23a; } .wc-rn i { background: #3f8fd8; } .wc-ab i { background: #e9604a; } .wc-re i { background: #f2cf3a; }
.wc-meter b { text-align: right; font-variant-numeric: tabular-nums; }
.wc-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; }

